def compute(vars):
    total_benefits = vars["v1"]
    benefits_affecting_effective_rate = vars["v2"]
    benefits_not_affecting_effective_rate = total_benefits - benefits_affecting_effective_rate

    if total_benefits == 0:
        return None

    percentage_not_affecting = benefits_not_affecting_effective_rate / total_benefits * 100

    return {
        "value": percentage_not_affecting,
        "trace": {
            "benefits_not_affecting_effective_rate": benefits_not_affecting_effective_rate,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
